// Versão grátis (comum): converte os dados de exemplo (ou o pedido do webhook) para o formato comum do pagamento.
let d = $('Sample payment data').first().json;
if (d.body && typeof d.body === 'object') d = d.body; // veio do webhook
return [{
  json: {
    pagamento: {
      origem: 'gratis',
      pagamento_id: d.pagamento_id || `teste-${Date.now()}`,
      moeda: 'EUR',
      total: d.valor,
      data_pagamento: null,
      cliente: {
        nome: d.nome || '', email: d.email || '', nif: d.nif || '', morada: d.morada || '',
        codigo_postal: d.codigo_postal || '', localidade: d.localidade || '', pais: 'PT',
      },
      itens: [{ descricao: d.descricao, quantidade: 1, valor: d.valor, taxa_iva: d.taxa_iva === undefined || d.taxa_iva === '' ? null : d.taxa_iva }],
    },
  },
}];

// ---- util (comum a todos os produtos Fluxo Pronto) ----
// Arredonda a N casas decimais.
function arred(n, casas) {
  const f = 10 ** casas;
  return Math.round((Number(n) + Number.EPSILON) * f) / f;
}

// Converte «19,90», «19.90» ou 19.9 em número (ou NaN).
function numero(v) {
  if (typeof v === 'number') return v;
  if (typeof v !== 'string') return NaN;
  const s = v.trim().replace(/\s/g, '');
  return Number(/,\d{1,2}$/.test(s) ? s.replace(/\./g, '').replace(',', '.') : s);
}

// Data e hora em Lisboa: { data: 'AAAA-MM-DD', dataHora: 'AAAA-MM-DD HH:MM:SS', dataPt: 'DD/MM/AAAA' }
function dataLisboa(d) {
  const s = d.toLocaleString('sv-SE', { timeZone: 'Europe/Lisbon', hour12: false }).replace('T', ' ');
  const data = s.slice(0, 10);
  return { data, dataHora: s.slice(0, 19), dataPt: `${data.slice(8, 10)}/${data.slice(5, 7)}/${data.slice(0, 4)}` };
}

// Escapa texto para HTML.
function html(t) {
  return String(t === undefined || t === null ? '' : t).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

// Valor em euros para mostrar: 24.6 -> «24,60».
function euros(v) {
  return Number(v).toFixed(2).replace('.', ',');
}

// Tapa segredos que possam aparecer em mensagens de erro (URLs com chaves, cabeçalhos, corpos JSON).
function taparSegredos(s) {
  return String(s || '')
    .replace(/(access_token|client_secret|password|refresh_token|username|api_key|apikey|mbKey|mbWayKey|boKey|key)=([^&\s"']+)/gi, '$1=***')
    .replace(/("(?:access_token|client_secret|password|api_key|mbKey|mbWayKey|boKey|apKey|key)"\s*:\s*")([^"]*)"/gi, '$1***"')
    .replace(/Bearer\s+[A-Za-z0-9_\-.]+/g, 'Bearer ***');
}

function faltaConfig(msg) { throw new Error(`CONFIGURAÇÃO INCOMPLETA: ${msg}`); }
function invalido(msg) { throw new Error(`DADOS INVÁLIDOS: ${msg}`); }
// ---- fim de util ----
// ---- nif (comum) ----
// Valida um NIF português (9 dígitos, prefixo permitido e dígito de controlo módulo 11).
function validarNifPortugues(nif) {
  if (!/^\d{9}$/.test(nif)) return false;
  const prefixos1 = ['1', '2', '3', '5', '6', '8'];
  const prefixos2 = ['45', '70', '71', '72', '74', '75', '77', '79', '90', '91', '98', '99'];
  if (!prefixos1.includes(nif[0]) && !prefixos2.includes(nif.slice(0, 2))) return false;
  let soma = 0;
  for (let i = 0; i < 8; i++) soma += Number(nif[i]) * (9 - i);
  const resto = soma % 11;
  const controlo = resto < 2 ? 0 : 11 - resto;
  return controlo === Number(nif[8]);
}

// Limpa o NIF recebido («PT 123 456 789» -> «123456789») e diz se é válido, estrangeiro, etc.
function analisarNif(bruto) {
  let s = String(bruto === undefined || bruto === null ? '' : bruto).toUpperCase().replace(/[\s.\-/]/g, '');
  if (!s) return { estado: 'vazio' };
  let pais = 'PT';
  const m = s.match(/^([A-Z]{2})(.+)$/);
  if (m) { pais = m[1]; s = m[2]; }
  if (pais !== 'PT') return { estado: 'estrangeiro', pais, valor: `${pais}${s}` };
  if (!validarNifPortugues(s)) return { estado: 'invalido', valor: s };
  if (s === '999999990') return { estado: 'consumidor_final', nif: s };
  return { estado: 'valido', nif: s };
}
// ---- fim de nif ----
// ---- pagamento (comum; precisa de util.js e nif.js) ----
// Lê as taxas de IVA da Configuração: taxas_iva (JSON «percentagem -> identificador») e taxa_iva_padrao.
function lerConfigIva(cfg) {
  let taxas = cfg.taxas_iva;
  if (typeof taxas === 'string') { try { taxas = JSON.parse(taxas); } catch (e) { faltaConfig('taxas_iva não é JSON válido'); } }
  taxas = taxas || {};
  const taxaPadrao = numero(cfg.taxa_iva_padrao);
  if (Number.isNaN(taxaPadrao)) faltaConfig('taxa_iva_padrao tem de ser um número (ex.: 23)');
  return { taxas, taxaPadrao };
}

// Valida um pagamento no formato comum (pagamento_id, moeda, total, data_pagamento, cliente, itens)
// e prepara as linhas com o preço unitário SEM IVA, escolhido para o total bater certo ao cêntimo.
// o = { taxaPadrao, motivoIsencao, descricaoPadrao, idTaxa(taxa, i), campoTaxa, extraLinha(item), idMax, casas, ondeCorrigir }
// Erros «DADOS INVÁLIDOS» = o pedido está mal (422); «CONFIGURAÇÃO INCOMPLETA» = falta configurar (500).
function validarPagamentoBase(p, o) {
  const avisos = [];
  const idMax = o.idMax || 50;
  const pagamentoId = String(p.pagamento_id || '').trim();
  if (!pagamentoId) invalido('falta pagamento_id (identificador único do pagamento).');
  if (pagamentoId.length > idMax) invalido(`pagamento_id tem mais de ${idMax} caracteres.`);
  if (!/^[A-Za-z0-9_.:\-]+$/.test(pagamentoId)) invalido('pagamento_id só pode ter letras, números e _ . : -');
  if (p.moeda !== 'EUR') invalido(`moeda ${p.moeda || '(vazia)'} não suportada; este workflow fatura só em euros.`);
  const total = arred(numero(p.total), 2);
  if (!(total > 0)) invalido('valor do pagamento em falta ou não positivo.');
  let dataPag = p.data_pagamento ? new Date(p.data_pagamento) : new Date();
  if (Number.isNaN(dataPag.getTime())) invalido('data do pagamento inválida (use o formato ISO, ex.: 2026-10-03T10:15:00Z).');
  if (dataPag.getTime() > Date.now() + 5 * 60 * 1000) dataPag = new Date();

  // Linhas
  let itens = Array.isArray(p.itens) ? p.itens : [];
  if (!itens.length) itens = [{ descricao: o.descricaoPadrao || 'Venda', quantidade: 1, valor: total, taxa_iva: null }];
  const campoTaxa = o.campoTaxa || 'id_taxa';
  const linhas = itens.map((it, i) => {
    const descricao = String(it.descricao || o.descricaoPadrao || 'Venda').trim().slice(0, 200);
    const qtd = numero(it.quantidade === undefined || it.quantidade === null ? 1 : it.quantidade);
    const valor = arred(numero(it.valor), 2);
    if (!(qtd > 0)) invalido(`item ${i + 1}: quantidade inválida.`);
    if (Number.isNaN(valor) || valor < 0) invalido(`item ${i + 1}: valor inválido.`);
    const taxa = it.taxa_iva === null || it.taxa_iva === undefined || it.taxa_iva === '' ? o.taxaPadrao : numero(it.taxa_iva);
    if (Number.isNaN(taxa) || taxa < 0 || taxa > 100) invalido(`item ${i + 1}: taxa de IVA inválida (${it.taxa_iva}).`);
    const idTaxa = o.idTaxa(taxa, i);
    if (taxa === 0 && !String(o.motivoIsencao || '').trim()) {
      faltaConfig('há itens a 0% de IVA: preencha motivo_isencao (código de isenção, ex.: M10) no nó «Configuration».');
    }
    return { descricao, quantidade: qtd, valor, taxa, [campoTaxa]: idTaxa, ...(o.extraLinha ? o.extraLinha(it) : {}) };
  });
  const somaItens = arred(linhas.reduce((s, l) => s + l.valor, 0), 2);
  if (Math.abs(somaItens - total) > 0.005) invalido(`a soma dos itens (${somaItens} €) é diferente do valor pago (${total} €).`);

  // Preço unitário sem IVA (as APIs recebem o preço sem imposto e aplicam a taxa).
  // Escolhe as casas decimais com que o total calculado bate certo com o valor pago.
  const casasPossiveis = o.casas || [4, 5, 6];
  let casasUsadas = null;
  for (const casas of casasPossiveis) {
    const tot = arred(linhas.reduce((s, l) => s + l.quantidade * arred(l.valor / l.quantidade / (1 + l.taxa / 100), casas) * (1 + l.taxa / 100), 0), 2);
    if (Math.abs(tot - total) < 0.005) { casasUsadas = casas; break; }
  }
  if (casasUsadas === null) {
    casasUsadas = casasPossiveis[casasPossiveis.length - 1];
    avisos.push(`O total calculado com o preço sem IVA pode diferir 1 cêntimo do valor pago. Confirme o total da fatura ${o.ondeCorrigir || 'no programa de faturação'}.`);
  }
  for (const l of linhas) l.preco_sem_iva = arred(l.valor / l.quantidade / (1 + l.taxa / 100), casasUsadas);

  // Email
  const c = p.cliente || {};
  const email = String(c.email || '').trim().toLowerCase();
  const emailValido = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email);
  if (email && !emailValido) avisos.push(`O email do cliente («${email}») não parece válido; a fatura não será enviada por email.`);

  return {
    pagamento: { ...p, pagamento_id: pagamentoId, total, cliente: { ...c, email: emailValido ? email : '' } },
    total, linhas, avisos, data_pagamento_js: dataPag,
  };
}

// Decide o cliente da fatura a partir do NIF: NIF português válido -> cliente com NIF;
// vazio, inválido ou estrangeiro -> consumidor final (com aviso), ou recusa se se_nif_invalido = parar.
// ondeCorrigir: «na Moloni», «no InvoiceXpress»…
function clienteFaturacao(c, seNifInvalido, ondeCorrigir, avisos) {
  const nif = analisarNif(c.nif);
  if (nif.estado === 'valido') {
    let cp = String(c.codigo_postal || '').trim();
    if (/^\d{7}$/.test(cp)) cp = `${cp.slice(0, 4)}-${cp.slice(4)}`;
    return {
      nif_estado: nif.estado,
      consumidor_final: false,
      nif: nif.nif,
      nome: String(c.nome || '').trim().slice(0, 100) || `Cliente ${nif.nif}`,
      email: c.email || '',
      morada: String(c.morada || '').trim().slice(0, 200),
      codigo_postal: /^\d{4}-\d{3}$/.test(cp) ? cp : '',
      localidade: String(c.localidade || '').trim().slice(0, 100),
    };
  }
  if (nif.estado === 'invalido' || nif.estado === 'estrangeiro') {
    const explicacao = nif.estado === 'invalido'
      ? `O NIF «${nif.valor}» não é um NIF português válido.`
      : `O número fiscal «${nif.valor}» não é português; este workflow só cria clientes com NIF português.`;
    if (String(seNifInvalido || 'consumidor_final') === 'parar') invalido(`${explicacao} (se_nif_invalido = parar)`);
    avisos.push(`${explicacao} A fatura foi emitida a consumidor final. Se o cliente precisar de fatura com NIF, corrija ${ondeCorrigir} (nota de crédito e nova fatura).`);
  }
  return { nif_estado: nif.estado, consumidor_final: true, nif: '999999990', nome: 'Consumidor final', email: '', morada: '', codigo_postal: '', localidade: '' };
}

// Procura, numa lista de documentos, o que tem exatamente esta referência (as pesquisas das APIs podem ser parciais).
function procurarPorReferencia(lista, campo, referencia) {
  return (Array.isArray(lista) ? lista : []).filter((d) => d && String(d[campo] || '') === String(referencia));
}
// ---- fim de pagamento ----
// Valida a configuração e o pagamento, valida o NIF e prepara as linhas da fatura com a taxa de IVA certa.
// Erros começados por «DADOS INVÁLIDOS» respondem 422 no webhook genérico; os outros respondem 500.
const cfg = $('Configuration').first().json;
const p = $input.first().json.pagamento || {};

// 1. Configuração
const base = String(cfg.invoicexpress_base_url || '');
if (!/^https?:\/\/[^/]+/.test(base) || /A-SUA-CONTA/i.test(base)) {
  faltaConfig('preencha invoicexpress_base_url com o endereço da sua conta (ex.: https://aminhaempresa.app.invoicexpress.com).');
}
const envio = String(cfg.envio_email || 'invoicexpress');
if (!['invoicexpress', 'smtp', 'nao'].includes(envio)) faltaConfig('envio_email tem de ser invoicexpress, smtp ou nao.');
if ('email_dono' in cfg && (!String(cfg.email_dono).includes('@') || !String(cfg.email_remetente || '').includes('@'))) {
  faltaConfig('preencha email_remetente e email_dono no nó «Configuration».');
}
const { taxas, taxaPadrao } = lerConfigIva(cfg);
const estadoDocumento = Number(cfg.estado_documento) === 0 ? 0 : 1;
const nomeArtigo = String(cfg.nome_artigo || '').trim() || 'Venda online';

// 2. Pagamento e linhas. Cada taxa de IVA -> nome do imposto no InvoiceXpress, também a 0%
//    (sem imposto na linha, o InvoiceXpress aplicaria o imposto por omissão da conta).
//    Preço sem IVA com 4 casas decimais, como nos exemplos da documentação.
const v = validarPagamentoBase(p, {
  taxaPadrao,
  motivoIsencao: cfg.motivo_isencao,
  descricaoPadrao: cfg.descricao_padrao,
  campoTaxa: 'imposto',
  ondeCorrigir: 'no InvoiceXpress',
  casas: [4],
  idTaxa: (taxa) => {
    const nome = String(taxas[String(taxa)] || '').trim();
    if (!nome) faltaConfig(`não há imposto do InvoiceXpress para a taxa de ${taxa}% em taxas_iva (nó «Configuration»; ex.: "${taxa}": "IVA${taxa}").`);
    return nome;
  },
  extraLinha: (it) => ({ artigo: String(it.invoicexpress_artigo || nomeArtigo).slice(0, 100) }),
});

// 3. Cliente. O InvoiceXpress identifica o cliente pelo «code» (aqui, o NIF): se não existir, cria-o;
//    se já existir, ignora os outros campos.
const c = clienteFaturacao(v.pagamento.cliente, cfg.se_nif_invalido, 'no InvoiceXpress', v.avisos);
const clienteIx = c.consumidor_final
  ? { name: 'Consumidor final', code: 'consumidor-final' }
  : {
    name: c.nome,
    code: c.nif,
    fiscal_id: c.nif,
    ...(c.email ? { email: c.email } : {}),
    ...(c.morada ? { address: c.morada } : {}),
    ...(c.localidade ? { city: c.localidade } : {}),
    ...(c.codigo_postal ? { postal_code: c.codigo_postal } : {}),
    country: String(cfg.pais_cliente || 'Portugal'),
  };

return [{
  json: {
    pagamento: v.pagamento,
    total: v.total,
    linhas: v.linhas,
    cliente_ix: clienteIx,
    consumidor_final: c.consumidor_final,
    nif_estado: c.nif_estado,
    data_documento: dataLisboa(new Date()).dataPt,
    estado_documento: estadoDocumento,
    envio_email: envio,
    avisos: v.avisos,
  },
}];

// ---- InvoiceXpress (só deste produto) ----
// Documentação: https://www.invoicexpress.com/api-v2 e https://docs.invoicexpress.com
// Lê a resposta (texto) de um pedido bem-sucedido. As respostas de erro (401, 404, 422…) vão para a saída
// de erro do nó HTTP e chegam ao alerta com a mensagem do n8n.
function lerRespostaIx(resposta, accao) {
  if (resposta === undefined || resposta === null || resposta === '') return {};
  if (typeof resposta === 'object') return resposta;
  try { return JSON.parse(resposta); } catch (e) {
    throw new Error(`InvoiceXpress (${accao}): resposta inesperada: ${String(resposta).slice(0, 300)}`);
  }
}

// A chave principal da resposta é o tipo de documento no singular (invoice_receipt); aceita também invoice e receipt.
function documentoIx(dados) {
  if (!dados || typeof dados !== 'object') return null;
  return dados.invoice_receipt || dados.invoice || dados.receipt || null;
}
// ---- fim de InvoiceXpress ----
// Confirma que cada imposto configurado existe no InvoiceXpress com a percentagem esperada.
// Importante: se o nome do imposto não existir, o InvoiceXpress aplica o imposto por omissão (documentação oficial).
const v = $('Validate payment and NIF').first().json;
const dados = lerRespostaIx($input.first().json.resposta, 'confirmar impostos');
const impostos = Array.isArray(dados.taxes) ? dados.taxes : [];
for (const l of v.linhas) {
  const imposto = impostos.find((t) => String(t.name) === l.imposto);
  if (!imposto) throw new Error(`CONFIGURAÇÃO INCOMPLETA: o imposto «${l.imposto}» (taxa de ${l.taxa}%) não existe nesta conta InvoiceXpress.`);
  if (Math.abs(Number(imposto.value) - l.taxa) > 0.001) {
    throw new Error(`CONFIGURAÇÃO INCOMPLETA: o imposto «${l.imposto}» no InvoiceXpress é de ${Number(imposto.value)}%, mas está configurado para ${l.taxa}%.`);
  }
}
return [{ json: { taxas_confirmadas: true } }];

// Monta o pedido POST /invoice_receipts.json (https://www.invoicexpress.com/api-v2/invoices/create).
// A chave principal é «invoice_receipt» (singular do tipo de documento) e as datas vão em dd/mm/aaaa.
// proprietary_uid = ID do pagamento: segundo a documentação, evita criações duplicadas em pedidos simultâneos.
const cfg = $('Configuration').first().json;
const v = $('Validate payment and NIF').first().json;

const fatura = {
  date: v.data_documento,
  due_date: v.data_documento,
  reference: v.pagamento.pagamento_id,
  client: v.cliente_ix,
  items: v.linhas.map((l) => ({
    name: l.artigo,
    description: l.descricao,
    unit_price: l.preco_sem_iva,
    quantity: l.quantidade,
    tax: { name: l.imposto },
  })),
};
if (Number(cfg.invoicexpress_sequence_id) > 0) fatura.sequence_id = String(Number(cfg.invoicexpress_sequence_id));
if (v.linhas.some((l) => l.taxa === 0)) fatura.tax_exemption = String(cfg.motivo_isencao).trim();
if (String(cfg.notas_documento || '').trim()) fatura.observations = String(cfg.notas_documento).trim();
return [{ json: { corpo: { invoice_receipt: fatura, proprietary_uid: v.pagamento.pagamento_id } } }];

// ---- InvoiceXpress (só deste produto) ----
// Documentação: https://www.invoicexpress.com/api-v2 e https://docs.invoicexpress.com
// Lê a resposta (texto) de um pedido bem-sucedido. As respostas de erro (401, 404, 422…) vão para a saída
// de erro do nó HTTP e chegam ao alerta com a mensagem do n8n.
function lerRespostaIx(resposta, accao) {
  if (resposta === undefined || resposta === null || resposta === '') return {};
  if (typeof resposta === 'object') return resposta;
  try { return JSON.parse(resposta); } catch (e) {
    throw new Error(`InvoiceXpress (${accao}): resposta inesperada: ${String(resposta).slice(0, 300)}`);
  }
}

// A chave principal da resposta é o tipo de documento no singular (invoice_receipt); aceita também invoice e receipt.
function documentoIx(dados) {
  if (!dados || typeof dados !== 'object') return null;
  return dados.invoice_receipt || dados.invoice || dados.receipt || null;
}
// ---- fim de InvoiceXpress ----
// Versão grátis: mostra o resultado.
const v = $('Validate payment and NIF').first().json;
const d = documentoIx(lerRespostaIx($input.first().json.resposta, 'criar rascunho')) || {};
return [{
  json: {
    resultado: 'Rascunho de fatura-recibo criado no InvoiceXpress. Abra-o no InvoiceXpress, confirme e finalize-o à mão.',
    result: 'Draft invoice-receipt created in InvoiceXpress. Open it in InvoiceXpress, check it and finalise it there.',
    document_id: d.id || null,
    total: d.total,
    nif: v.consumidor_final ? `consumidor final (NIF ${v.nif_estado})` : v.cliente_ix.fiscal_id,
    avisos: v.avisos,
    versao_completa: 'A versão completa emite a fatura finalizada logo a seguir ao pagamento (Stripe ou webhook), envia-a ao cliente por email, não duplica faturas e avisa-o se algo falhar.',
  },
}];
